def solve() -> int:
    hourly_rate = 15
    overtime_rate = 20
    hours_worked = 45
    if hours_worked <= 35:
        total_earnings = hourly_rate * hours_worked
    else:
        total_earnings = hourly_rate * 35 + overtime_rate * (hours_worked - 35)
    result = total_earnings
    return result

